import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import hmac

app = Flask(__name__)
UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/var/spool/conversions')
API_SECRET = os.environ.get('API_SECRET', 'changeme')
ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'webp', 'pdf']

def verify_signature(payload, signature):
    expected = hmac.new(API_SECRET.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.before_request
def authenticate():
    if request.path == '/health':
        return None
    token = request.headers.get('X-Api-Token', '')
    if not hmac.compare_digest(token, API_SECRET):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/convert', methods=['POST'])
def convert_document():
    """Convert uploaded file to target format using ImageMagick/LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'no file provided'}), 400

    target_format = request.form.get('format', 'pdf')
    density = request.form.get('density', '150')
    quality = request.form.get('quality', '90')
    extra_args = request.form.get('args', '')

    # Validate target format
    if target_format not in ALLOWED_FORMATS:
        return jsonify({'error': f'unsupported format: {target_format}'}), 400

    # Validate numeric params
    try:
        int(density)
        int(quality)
    except ValueError:
        return jsonify({'error': 'density and quality must be integers'}), 400

    uploaded = request.files['file']
    filename = secure_filename(uploaded.filename)
    if not filename:
        return jsonify({'error': 'invalid filename'}), 400

    input_path = os.path.join(UPLOAD_DIR, f'input_{filename}')
    output_name = f'output_{os.path.splitext(filename)[0]}.{target_format}'
    output_path = os.path.join(UPLOAD_DIR, output_name)

    uploaded.save(input_path)

    # Build conversion command
    # extra_args allows power users to pass additional ImageMagick flags
    # like -resize, -rotate, -strip, etc.
    cmd = f'convert -density {density} -quality {quality} {extra_args} {input_path} {output_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )
        if result.returncode != 0:
            stderr_msg = result.stderr.decode('utf-8', errors='replace')[:500]
            return jsonify({'error': 'conversion failed', 'details': stderr_msg}), 500

        return send_file(output_path, as_attachment=True, download_name=output_name)
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'conversion timed out'}), 504
    finally:
        # Cleanup
        for p in [input_path, output_path]:
            try:
                os.unlink(p)
            except OSError:
                pass

@app.route('/api/v1/metadata', methods=['POST'])
def extract_metadata():
    """Extract EXIF/metadata from uploaded file"""
    if 'file' not in request.files:
        return jsonify({'error': 'no file provided'}), 400

    uploaded = request.files['file']
    filename = secure_filename(uploaded.filename)
    input_path = os.path.join(UPLOAD_DIR, f'meta_{filename}')
    uploaded.save(input_path)

    try:
        result = subprocess.run(
            ['identify', '-verbose', input_path],
            capture_output=True,
            timeout=10
        )
        metadata = result.stdout.decode('utf-8', errors='replace')
        return jsonify({'metadata': metadata})
    finally:
        try:
            os.unlink(input_path)
        except OSError:
            pass

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
